// Demo photos are illustrative and travel with the product in saved store data.
const apparelPhotos = {
  "nike-tee": "data:image/webp;base64,",
  "champion-hoodie": "data:image/webp;base64,"
};
const apparelBanner = 'Винтажная одежда любимых брендов';
const apparelSamples = [
  { category: 'Футболки', id: 'nike-tee', name: 'Nike Swoosh · футболка', group: 'nike-swoosh', sizes: ['M', 'L'], color: 'Белый', price: 3490 },
  { category: 'Толстовки', id: 'champion-hoodie', name: 'Champion · худи', group: 'champion-hoodie', sizes: ['S', 'M', 'L'], color: 'Зелёный', price: 5990 },
];

function addApparelAssortment(store) {
  if (store.apparelAssortmentAdded) return store;
  if (store.settings.banner === 'Rare denim. Real vintage. Real style.') store.settings.banner = apparelBanner;

  for (const { category, id, name, group, sizes, color, price } of apparelSamples) {
    let cat = store.categories.findIndex((name, index) => name === category && !store.categoryInfo?.[index]?.deleted);
    if (cat === -1) cat = store.categories.push(category) - 1;
    for (const size of sizes) {
      const variantId = id + '-' + size.toLowerCase();
      if (store.products.some(product => product.id === variantId)) continue;
      store.products.push({
        id: variantId, group, name, size, color, price, cat, fresh: 1, stock: 1,
        image: apparelPhotos[id],
      });
    }
  }
  store.apparelAssortmentAdded = true;
  return store;
}
